mapper.select:
SELECT ct.id, ct.title, ct.content_type, ct.category_id, ct.cover_url, ct.summary, ct.status, ct.sort, ct.view_count, ct.favorite_count, ct.publish_time, ct.scheduled_publish_time, ct.created_at, ct.updated_at FROM content ct LEFT JOIN category cg ON cg.id = ct.category_id AND cg.deleted = 0 WHERE ct.deleted = 0
AND ct.category_id IN
#{categoryId}
AND ct.content_type = #{query.contentType}
AND ct.status = #{query.status}
AND ct.title LIKE #{query.keywordPattern} ESCAPE '!'
AND ct.publish_time >= #{query.publishTimeFrom}
AND ct.publish_time <= #{query.publishTimeTo}
AND ct.scheduled_publish_time IS NULL
AND ct.status = 'DRAFT' AND ct.scheduled_publish_time IS NOT NULL
ORDER BY ct.publish_time DESC, ct.id DESC
ORDER BY cg.sort ASC, cg.id ASC, ct.sort ASC, ct.publish_time DESC, ct.id DESC

mapper.update:
UPDATE content
SET scheduled_publish_time = NULL,
    updated_at = #{now}
WHERE id = #{id}
  AND deleted = 0

mapper.select:
SELECT COUNT(*)
FROM content ct
WHERE ct.deleted = 0
  AND ct.created_at >= #{from}
  AND ct.created_at < #{to}
